-- Seed A2 learning lessons for the new /aprender/a2 page.
INSERT OR IGNORE INTO learning_courses (id, title, level, description, published) VALUES ('english-a2', 'English A2: Next Steps', 'A2', 'Curso A2 con explicaciones en español, ejemplos contextualizados y práctica guiada.', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-01', 'english-a2', 1, 1, 'Past Simple: verbos regulares', 'Contar acciones terminadas en el pasado utilizando verbos regulares.', 15, '{"objective":"Contar acciones terminadas en el pasado utilizando verbos regulares.","sections":[{"type":"learn","title":"Past Simple","body":"Usamos el Past Simple para acciones terminadas en un momento pasado. En afirmativa, los verbos regulares suelen acabar en -ed."},{"type":"example","title":"Ejemplos","body":"I watched a film yesterday = Vi una película ayer. She visited her aunt = Ella visitó a su tía."},{"type":"practice","title":"Negativas y preguntas","body":"Negativa: sujeto + didn’t + verbo base. Pregunta: Did + sujeto + verbo base? Ejemplo: Did you work yesterday?"}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-02', 'english-a2', 2, 1, 'Past Simple: verbos irregulares', 'Utilizar verbos irregulares frecuentes para hablar de experiencias pasadas.', 15, '{"objective":"Utilizar verbos irregulares frecuentes para hablar de experiencias pasadas.","sections":[{"type":"learn","title":"Verbos clave","body":"go → went; have → had; see → saw; buy → bought; eat → ate; make → made."},{"type":"example","title":"Ejemplos","body":"We went to the beach = Fuimos a la playa. I saw my friends = Vi a mis amigos."},{"type":"practice","title":"Recuerda","body":"Con did y didn’t, el verbo vuelve a su forma base: Did you go? / I didn’t go."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-03', 'english-a2', 3, 1, 'Preguntas en pasado', 'Formar preguntas y respuestas breves sobre acontecimientos pasados.', 15, '{"objective":"Formar preguntas y respuestas breves sobre acontecimientos pasados.","sections":[{"type":"learn","title":"Estructura","body":"Did + sujeto + verbo base? What did you do? Where did she go?"},{"type":"example","title":"Respuestas breves","body":"Yes, I did. / No, I didn’t. Para el verbo be: Was he tired? Were they at home?"},{"type":"practice","title":"Diálogo","body":"Where did you go? — I went to Madrid. = ¿Adónde fuiste? — Fui a Madrid."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-04', 'english-a2', 4, 1, 'Comparativos', 'Comparar personas, lugares y objetos utilizando adjetivos.', 15, '{"objective":"Comparar personas, lugares y objetos utilizando adjetivos.","sections":[{"type":"learn","title":"Adjetivos cortos","body":"Añade -er: small → smaller, cheap → cheaper. Después usa than."},{"type":"example","title":"Adjetivos largos","body":"Usa more + adjetivo: more expensive, more comfortable."},{"type":"practice","title":"Irregulares","body":"good → better; bad → worse. This hotel is cheaper than that one."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-05', 'english-a2', 5, 1, 'Superlativos', 'Describir el extremo de una cualidad en un grupo.', 15, '{"objective":"Describir el extremo de una cualidad en un grupo.","sections":[{"type":"learn","title":"Regla","body":"Adjetivo corto + -est: the smallest. Adjetivo largo: the most interesting."},{"type":"example","title":"Irregulares","body":"good → the best; bad → the worst."},{"type":"practice","title":"Ejemplo","body":"It’s the best restaurant in town = Es el mejor restaurante de la ciudad."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-06', 'english-a2', 6, 1, 'Adverbios de modo', 'Explicar cómo se realiza una acción.', 15, '{"objective":"Explicar cómo se realiza una acción.","sections":[{"type":"learn","title":"Formación","body":"Muchos adverbios se forman con adjetivo + -ly: slow → slowly, careful → carefully."},{"type":"example","title":"Irregulares","body":"good → well; fast → fast; hard → hard."},{"type":"practice","title":"Ejemplo","body":"She speaks English slowly = Ella habla inglés despacio."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-07', 'english-a2', 7, 1, 'Preposiciones de tiempo', 'Usar in, on y at para indicar cuándo sucede algo.', 15, '{"objective":"Usar in, on y at para indicar cuándo sucede algo.","sections":[{"type":"learn","title":"IN","body":"Meses, años y partes del día: in July, in 2026, in the morning."},{"type":"example","title":"ON","body":"Días y fechas: on Monday, on 5 May."},{"type":"practice","title":"AT","body":"Horas y expresiones concretas: at 7 o’clock, at night."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-08', 'english-a2', 8, 1, 'Preposiciones de lugar y movimiento', 'Indicar ubicación y desplazamiento en situaciones cotidianas.', 15, '{"objective":"Indicar ubicación y desplazamiento en situaciones cotidianas.","sections":[{"type":"learn","title":"Lugar","body":"next to = al lado de; between = entre; opposite = enfrente de; behind = detrás de."},{"type":"example","title":"Movimiento","body":"across = cruzando; through = a través de; towards = hacia."},{"type":"practice","title":"Ejemplo","body":"The bank is opposite the station = El banco está enfrente de la estación."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-09', 'english-a2', 9, 1, 'Experiencias personales', 'Hablar sobre experiencias y acontecimientos que han sido importantes.', 15, '{"objective":"Hablar sobre experiencias y acontecimientos que han sido importantes.","sections":[{"type":"learn","title":"Useful phrases","body":"I visited…; I tried…; I enjoyed…; It was exciting."},{"type":"example","title":"Conectores","body":"First, then, after that y finally ayudan a ordenar una historia."},{"type":"practice","title":"Mini tarea","body":"Cuenta tres cosas que hiciste el fin de semana pasado."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-10', 'english-a2', 10, 1, 'Repaso del módulo 1', 'Consolidar el pasado simple y las descripciones.', 15, '{"objective":"Consolidar el pasado simple y las descripciones.","sections":[{"type":"learn","title":"Past Simple","body":"I went / I didn’t go / Did you go? Usa la forma base después de did y didn’t."},{"type":"example","title":"Comparaciones","body":"cheaper than; more interesting than; the best; the most beautiful."},{"type":"practice","title":"Reto","body":"Escribe cinco frases sobre un viaje y compara dos lugares."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-11', 'english-a2', 11, 2, 'Present Perfect: introducción', 'Introducir el Present Perfect para conectar experiencias pasadas con el presente.', 15, '{"objective":"Introducir el Present Perfect para conectar experiencias pasadas con el presente.","sections":[{"type":"learn","title":"Forma","body":"Sujeto + have/has + participio pasado."},{"type":"example","title":"Ejemplos","body":"I have visited Rome = He visitado Roma. She has tried sushi = Ella ha probado sushi."},{"type":"practice","title":"Have o has","body":"I/you/we/they have; he/she/it has."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-12', 'english-a2', 12, 2, 'Ever y never', 'Preguntar y hablar de experiencias que alguna vez se han tenido.', 15, '{"objective":"Preguntar y hablar de experiencias que alguna vez se han tenido.","sections":[{"type":"learn","title":"Ever","body":"Have you ever…? significa ¿Has… alguna vez?"},{"type":"example","title":"Never","body":"I have never flown = Nunca he volado. Never ya da sentido negativo."},{"type":"practice","title":"Respuestas","body":"Yes, I have. / No, I haven’t."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-13', 'english-a2', 13, 2, 'Already y yet', 'Expresar si algo ya ha sucedido o todavía no.', 15, '{"objective":"Expresar si algo ya ha sucedido o todavía no.","sections":[{"type":"learn","title":"Already","body":"Se usa principalmente en afirmativas: I have already finished."},{"type":"example","title":"Yet","body":"Suele aparecer al final de preguntas y negativas: Have you finished yet? I haven’t finished yet."},{"type":"practice","title":"Traducción","body":"already = ya; yet = ya/todavía, según el contexto."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-14', 'english-a2', 14, 2, 'Just', 'Decir que una acción acaba de suceder.', 15, '{"objective":"Decir que una acción acaba de suceder.","sections":[{"type":"learn","title":"Posición","body":"Have/has + just + participio."},{"type":"example","title":"Ejemplos","body":"I’ve just arrived = Acabo de llegar. She’s just called = Ella acaba de llamar."},{"type":"practice","title":"Práctica","body":"Completa: They have just ____ (leave). Respuesta: left."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-15', 'english-a2', 15, 2, 'Present Perfect o Past Simple', 'Diferenciar experiencias sin fecha concreta de acciones en un pasado terminado.', 15, '{"objective":"Diferenciar experiencias sin fecha concreta de acciones en un pasado terminado.","sections":[{"type":"learn","title":"Present Perfect","body":"I have seen that film: experiencia, sin decir cuándo."},{"type":"example","title":"Past Simple","body":"I saw that film last night: se especifica cuándo."},{"type":"practice","title":"Pistas","body":"yesterday, last week, in 2024 → Past Simple; ever, never, already → a menudo Present Perfect."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-16', 'english-a2', 16, 2, 'Past Continuous', 'Describir una acción que estaba en progreso en un momento pasado.', 15, '{"objective":"Describir una acción que estaba en progreso en un momento pasado.","sections":[{"type":"learn","title":"Forma","body":"was/were + verbo-ing."},{"type":"example","title":"Ejemplos","body":"I was studying at 8 pm = Estaba estudiando a las ocho."},{"type":"practice","title":"Uso","body":"I was cooking when he arrived = Estaba cocinando cuando llegó."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-17', 'english-a2', 17, 2, 'Past Simple y Past Continuous', 'Narrar sucesos y acciones en progreso al mismo tiempo.', 15, '{"objective":"Narrar sucesos y acciones en progreso al mismo tiempo.","sections":[{"type":"learn","title":"Contraste","body":"Past Continuous describe el fondo; Past Simple la acción que ocurre."},{"type":"example","title":"Ejemplo","body":"We were walking when it started to rain."},{"type":"practice","title":"While y when","body":"While suele acompañar una acción en progreso; when introduce el acontecimiento."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-18', 'english-a2', 18, 2, 'For y since', 'Expresar cuánto tiempo dura una situación.', 15, '{"objective":"Expresar cuánto tiempo dura una situación.","sections":[{"type":"learn","title":"For","body":"Se usa con un periodo: for two years, for a week."},{"type":"example","title":"Since","body":"Se usa con un punto de inicio: since Monday, since 2022."},{"type":"practice","title":"Ejemplo","body":"I have lived here for three years / since 2023."}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-19', 'english-a2', 19, 2, 'Preguntas con how', 'Preguntar por duración, frecuencia, cantidad y forma.', 15, '{"objective":"Preguntar por duración, frecuencia, cantidad y forma.","sections":[{"type":"learn","title":"How long","body":"How long have you lived here? = ¿Cuánto tiempo llevas viviendo aquí?"},{"type":"example","title":"How often","body":"How often do you exercise? = ¿Con qué frecuencia haces ejercicio?"},{"type":"practice","title":"How much/many","body":"How much water? How many books?"}],"reviewEnabled":true}', 1);
INSERT OR IGNORE INTO learning_lessons (id, course_id, lesson_number, unit_number, title, objective, estimated_minutes, content_json, published) VALUES ('a2-20', 'english-a2', 20, 2, 'Repaso del módulo 2', 'Consolidar las formas del presente perfecto y del pasado continuo.', 15, '{"objective":"Consolidar las formas del presente perfecto y del pasado continuo.","sections":[{"type":"learn","title":"Repaso","body":"Have/has + participio; was/were + -ing."},{"type":"example","title":"Contraste temporal","body":"I’ve just finished vs I finished an hour ago."},{"type":"practice","title":"Reto","body":"Cuenta una experiencia y describe qué estaba pasando cuando ocurrió."}],"reviewEnabled":true}', 1);
